-- ========================================================


function DreamSpace_EndStory:__init()
    self.controller = nil
    self.co = nil   -- 发送携程请求
    self.isInit = false
end


function DreamSpace_EndStory:__delete()
    self.co = nil
end





function DreamSpace_EndStory:Start()
    KTool.SetActive(self.controller.gameObject, true);


    assert( self.enterTriggerBH )
    self.enterTrigger = DreamSpaceLuaUtils.GetLuaScr(self.enterTriggerBH.gameObject, "Game.DreamSpace.Level1.Story.CollideTrigger" )

    assert( self.enterTrigger )
    self.enterTrigger.WhenTriggerEnter = function(other_)
        self.enterTrigger:SetActive(false) -- 立刻关闭 入口 collider
        DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
        self.co_1 = cs_coroutine.start( self.Play_1, self )
        
        DreamSpaceSounds.Play( DreamSpaceSounds.music.dream )
    end

    ---  
    assert( self.vcam_1 and self.vcam_2 )
    self.vcam_1.enabled = false
    self.vcam_2.enabled = false

    self.quest = DreamSpaceLuaUtils.GetLuaScr(self.questBH.gameObject, "Game.DreamSpace.Level1.Quest.QuestLvl1" )

    ---
    DreamSpaceLuaUtils.StopCoroutine( self.co )
    self.co = cs_coroutine.start(self.DelayInit, self)
end


function DreamSpace_EndStory:DelayInit() 

    cs_coroutine.yield_return( DreamSpaceStory.WaitInstance() ) -- 等待实例化
    self.dreamSpaceStory = DreamSpaceStory.GetInstance()   -- 拿到唯一实例

    cs_coroutine.yield_return( DreamSpace_FullScreen.WaitInstance() ) -- 等待实例化
    self.dreamSpace_FullScreen = DreamSpace_FullScreen.GetInstance()   -- 拿到唯一实例


    for i = 0, DreamSpaceStates.DelayInitWaitFrames do
        self.vcam3rdPersonFollow = GlobalsInDreamSpace.FindComponent("vcam3rdPersonFollow") -- CinemachineVirtualCamera
        if isNotNull(self.vcam3rdPersonFollow) then
            break
        end
        coroutine.yield(Yielders.EndOfFrame)
    end
    if isNull(self.vcam3rdPersonFollow) then
        printError("始终没能找到 vcam3rdPersonFollow, 请查找原因")
        return
    end

    cs_coroutine.yield_return( DreamSpace_Postprocessing.WaitInstance() ) -- 等待实例化
    self.dreamSpace_Postprocessing = DreamSpace_Postprocessing.GetInstance()   -- 拿到唯一实例

    self.isInit = true
end



function DreamSpace_EndStory:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co )
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co = nil
    self.co_1 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


-- ===============================================================



function DreamSpace_EndStory:Play_1() 
    -- 等待初始化成功:
    while self.isInit == false do
        coroutine.yield(Yielders.EndOfFrame)
    end

    DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Lock ) -- PC 版 禁止打开 ui 子界面 
    DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Lock ) -- 希望禁止玩家输入

    -- 隐藏 DreamSpace UI:
    local RoleControllerRootCanvasMgr = import('Game.DreamSpace.UI.RoleControllerRootCanvasMgr'):GetInstance()
    RoleControllerRootCanvasMgr:CheckOrInitSync()
    RoleControllerRootCanvasMgr:ShowOrHide( false  ) -- hide

    
    -- 黑屏淡入:
    self.dreamSpace_FullScreen:SwitchToBlack( 10.0 )
    while self.dreamSpace_FullScreen:GetIsDirty() == true do
        coroutine.yield(Yielders.EndOfFrame)
    end

    -- cut:
    self.vcam3rdPersonFollow.enabled = false
    self.vcam_1.enabled = true

    -- 黑屏淡出:
    self.dreamSpace_FullScreen:SwitchToTransparent( 8.0 )
    while self.dreamSpace_FullScreen:GetIsDirty() == true do
        coroutine.yield(Yielders.EndOfFrame)
    end
    

    print( "--- 结尾故事 -1- ----" )
    cs_coroutine.yield_return( self.dreamSpaceStory:PlayStory( 1006 ) ) 


    -- todo: 表达方式有待商榷

    -- 回到 role 相机:
    self.vcam3rdPersonFollow.enabled = true
    self.vcam_1.enabled = false
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 1.0 ))

    --在此时关闭浮标
    self.quest.floatingMarkerManager:EnableMarker(false)

    -- 显示 DreamSpace UI:
    RoleControllerRootCanvasMgr:ShowOrHide( true  ) -- show

    DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- 解除禁止:玩家输入  
    DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- PC 版 允许打开 ui 子界面 
end



function DreamSpace_EndStory:Play_2() 
    -- 等待初始化成功:
    while self.isInit == false do
        coroutine.yield(Yielders.EndOfFrame)
    end

    DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Lock ) -- PC 版 禁止打开 ui 子界面 
    DreamSpaceStates.LockViewRotate_ByFlag( DreamSpaceStates.InputLockState.Lock ) -- 禁止玩家旋转视角

    -- 画面后处理效果: 回忆模式 
    -- 之后无需恢复回 彩色模式:
    self.dreamSpace_Postprocessing:SwitchToMemory( 2.5 )

    -- 猫 只能走向 漩涡出口:
    InputManager.SetMoveInputMagnitudeConstraint( nil, 0.1 ) -- 慢速走路


    -- 缓动到 相机 2:
    self.vcam3rdPersonFollow.enabled = false
    self.vcam_2.enabled = true


    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.5 ))

end









return DreamSpace_EndStory
